<script setup lang="ts">
import { onMounted, reactive, ref } from "vue"; import { ElMessage } from "element-plus"; import { http } from "../api";
const rows=ref<any[]>([]), keyword=ref(""), dialog=ref(false); const form=reactive<any>({part_number:"",name:"",oe_number:"",unit:"个",purchase_price:0,sale_price:0,location:""});
async function load(){rows.value=await http.get("/parts",{params:{keyword:keyword.value||undefined}})} async function save(){await http.post("/parts",form);dialog.value=false;Object.assign(form,{part_number:"",name:"",oe_number:"",unit:"个",purchase_price:0,sale_price:0,location:""});ElMessage.success("零件已新增");await load()} async function remove(row:any){await http.delete(`/parts/${row.id}`);await load()} onMounted(load);
</script>
<template><div class="page-actions"><div><el-input v-model="keyword" placeholder="搜索零件" style="width:320px" @keyup.enter="load"/><el-button @click="load">查询</el-button></div><el-button type="primary" @click="dialog=true">新增零件</el-button></div>
<div class="panel"><el-table :data="rows" stripe><el-table-column prop="part_number" label="编号"/><el-table-column prop="oe_number" label="OE号"/><el-table-column prop="name" label="名称"/><el-table-column prop="unit" label="单位"/><el-table-column prop="location" label="货位"/><el-table-column label="进价"><template #default="{row}">¥{{(row.purchase_price/100).toFixed(2)}}</template></el-table-column><el-table-column label="售价"><template #default="{row}">¥{{(row.sale_price/100).toFixed(2)}}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div>
<el-dialog v-model="dialog" title="新增零件" width="560"><el-form :model="form" label-width="90"><el-form-item label="零件编号"><el-input v-model="form.part_number"/></el-form-item><el-form-item label="零件名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="OE号"><el-input v-model="form.oe_number"/></el-form-item><el-form-item label="单位"><el-input v-model="form.unit"/></el-form-item><el-form-item label="货位"><el-input v-model="form.location"/></el-form-item><el-form-item label="参考进价(分)"><el-input-number v-model="form.purchase_price" :min="0"/></el-form-item><el-form-item label="参考售价(分)"><el-input-number v-model="form.sale_price" :min="0"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
